#!/usr/bin/env python3
"""Build a self-contained HTML dashboard from inference summary CSV files."""

from __future__ import annotations

import argparse
import csv
import json
from pathlib import Path


DATASETS = (
    "kpi", "cluster_summary", "journey_type_summary", "family_summary",
    "cluster_heatmap", "family_heatmap", "daily_trend", "friction_summary",
    "friction_by_type", "novel_daily", "novel_entry_exit",
    "next_action_summary", "session_composition", "journey_examples",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input-dir", type=Path, required=True)
    parser.add_argument("--output", type=Path, help="default: <input-dir>/index.html")
    parser.add_argument("--title", default="HiFPT Journey Intelligence")
    return parser.parse_args()


def read_csv(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        raise SystemExit(f"missing dashboard dataset: {path}")
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def build(args: argparse.Namespace) -> Path:
    input_dir = args.input_dir.resolve()
    output = (args.output or input_dir / "index.html").resolve()
    datasets = {name: read_csv(input_dir / f"{name}.csv") for name in DATASETS}
    manifest_path = input_dir / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8")) if manifest_path.exists() else {}
    payload = json.dumps({"tables": datasets, "manifest": manifest}, ensure_ascii=False, separators=(",", ":"))
    safe_payload = payload.replace("</", "<\\/")
    html = TEMPLATE.replace("__TITLE__", escape_html(args.title)).replace("__DATA__", safe_payload)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(html, encoding="utf-8")
    print(f"Built {output} ({output.stat().st_size / 1e6:.1f} MB)")
    return output


def escape_html(value: str) -> str:
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


TEMPLATE = r'''<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__</title>
<style>
:root{--ink:#172033;--muted:#667085;--blue:#2c6bb3;--blue2:#6ca8e6;--red:#dc5a5a;--amber:#e8a93d;--green:#2f9b77;--paper:#fff;--bg:#f4f6fa;--line:#e3e8ef;--shadow:0 8px 28px rgba(22,38,66,.07)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:245px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;height:100vh;padding:26px 18px;background:#17233a;color:#eef4ff}.brand{font-size:19px;font-weight:800;letter-spacing:-.3px}.brand span{color:#74b5ff}.side p{color:#aebbd0;font-size:12px}.nav{margin-top:30px}.nav a{display:block;padding:9px 11px;margin:3px 0;color:#cbd5e6;text-decoration:none;border-radius:8px}.nav a:hover{background:#243552;color:#fff}.side-foot{position:absolute;bottom:22px;font-size:11px;color:#8190a9}.main{min-width:0;padding:28px 32px 60px}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}.eyebrow{text-transform:uppercase;color:var(--blue);font-weight:800;font-size:11px;letter-spacing:1.2px}.top h1{margin:5px 0 4px;font-size:29px;letter-spacing:-.8px}.subtitle{margin:0;color:var(--muted)}.controls{display:flex;gap:10px}.control{background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 11px}.control label{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;font-weight:700}.control select,.control input{border:0;outline:0;font:inherit;color:var(--ink);background:transparent;min-width:120px}.kpis{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:12px;margin:24px 0}.card,.panel{background:var(--paper);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}.kpi{padding:16px}.kpi .label{color:var(--muted);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.35px}.kpi .value{font-size:24px;font-weight:800;margin-top:7px;letter-spacing:-.5px}.kpi .note{font-size:11px;color:var(--muted);margin-top:2px}.section{scroll-margin-top:20px;margin-top:26px}.section-title{display:flex;align-items:end;justify-content:space-between;margin:0 0 11px}.section-title h2{font-size:18px;margin:0}.section-title p{margin:0;color:var(--muted);font-size:12px}.grid-2{display:grid;grid-template-columns:1.25fr .75fr;gap:14px}.grid-even{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel{padding:17px;min-width:0}.panel h3{font-size:14px;margin:0 0 3px}.hint{color:var(--muted);font-size:11px;margin-bottom:13px}.bars{display:grid;gap:8px}.bar-row{display:grid;grid-template-columns:minmax(130px,2fr) minmax(110px,3fr) 74px;align-items:center;gap:9px}.bar-label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.bar-track{height:9px;background:#eef2f7;border-radius:20px;overflow:hidden}.bar-fill{height:100%;background:linear-gradient(90deg,var(--blue),var(--blue2));border-radius:20px}.bar-fill.red{background:linear-gradient(90deg,#e49374,var(--red))}.bar-fill.green{background:linear-gradient(90deg,#67c6a7,var(--green))}.bar-value{text-align:right;font-variant-numeric:tabular-nums;font-size:11px;color:var(--muted)}.heat-scroll{overflow:auto;max-height:600px}.heatmap{display:grid;grid-template-columns:minmax(235px,1fr) repeat(24,20px);gap:2px;align-items:center;min-width:750px}.heat-label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:11px;padding-right:7px}.heat-head{text-align:center;color:var(--muted);font-size:9px}.cell{height:16px;border-radius:2px;cursor:help}.legend{display:flex;align-items:center;gap:7px;justify-content:flex-end;color:var(--muted);font-size:10px;margin-top:8px}.legend-gradient{width:100px;height:7px;background:linear-gradient(90deg,#edf2f8,#2c6bb3);border-radius:7px}.svg-chart{width:100%;height:300px;display:block}.axis{stroke:#dce3ed;stroke-width:1}.area{fill:rgba(44,107,179,.13)}.line{fill:none;stroke:var(--blue);stroke-width:2.5}.line.red{stroke:var(--red)}.dot{fill:#fff;stroke:var(--blue);stroke-width:1.5}.tick{font-size:9px;fill:#788397}.table-wrap{overflow:auto;max-height:520px;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:12px}th{position:sticky;top:0;background:#f7f9fc;text-align:left;color:#5f6b7d;font-size:10px;text-transform:uppercase;letter-spacing:.3px;z-index:1}th,td{padding:9px 10px;border-bottom:1px solid #edf0f4;vertical-align:top}tbody tr:hover{background:#f8fbff}.pill{display:inline-flex;border-radius:20px;padding:3px 7px;font-size:10px;font-weight:700;background:#eaf2fc;color:#245d9f}.pill.bad{background:#fdeceb;color:#af3f3f}.split{display:flex;gap:9px;align-items:center}.search{width:250px;padding:8px 10px;border:1px solid var(--line);border-radius:9px;background:#fff}.empty{padding:30px;text-align:center;color:var(--muted)}.journey{padding:13px 0;border-bottom:1px solid var(--line)}.journey:last-child{border:0}.journey-head{display:flex;justify-content:space-between;gap:10px}.journey-title{font-weight:700}.meta{font-size:11px;color:var(--muted)}details{margin-top:7px}summary{cursor:pointer;color:var(--blue);font-size:11px}pre{white-space:pre-wrap;word-break:break-word;background:#f5f7fa;padding:11px;border-radius:8px;font-size:11px;max-height:240px;overflow:auto}.footer{margin-top:30px;color:var(--muted);font-size:11px;text-align:center}
.treemap-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.8fr);gap:18px}.treemap-frame{background:#353637;padding:6px;min-height:560px}.treemap-svg{display:block;width:100%;height:550px}.tree-family{fill:none;stroke:#f7f8fa;stroke-width:2}.tree-cell{stroke:#fff;stroke-width:1.3;transition:opacity .15s}.tree-cell:hover{opacity:.8}.tree-label{font-size:10px;fill:#273142;pointer-events:none}.tree-label.light{fill:#fff}.tree-family-label{font-size:13px;font-weight:750;fill:#202a3a;pointer-events:none}.tree-side{padding:8px 2px}.tree-side h3{margin:0 0 15px}.tree-insight{font-size:16px;line-height:1.6;margin-top:25px;padding-top:18px;border-top:1px solid var(--line)}.tree-insight strong{font-weight:800}.treemap-legend{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:10px;margin-top:9px}.treemap-gradient{width:130px;height:9px;background:linear-gradient(90deg,#4c78a8,#eeca3b,#e45756);border-radius:7px}
@media(max-width:1100px){.shell{grid-template-columns:1fr}.side{display:none}.main{padding:22px}.kpis{grid-template-columns:repeat(3,1fr)}.grid-2,.grid-even,.treemap-layout{grid-template-columns:1fr}}@media(max-width:650px){.top{display:block}.controls{margin-top:16px}.kpis{grid-template-columns:repeat(2,1fr)}.main{padding:15px}.section-title{display:block}.section-title p{margin-top:3px}.bar-row{grid-template-columns:120px 1fr 58px}.treemap-frame{min-height:420px}.treemap-svg{height:410px}}
</style>
</head>
<body><div class="shell">
<aside class="side"><div class="brand">HiFPT <span>Journey</span></div><p>Production inference intelligence</p><nav class="nav"><a href="#overview">Tổng quan</a><a href="#landscape">Cluster landscape</a><a href="#timing">User đang làm gì?</a><a href="#trend">Xu hướng</a><a href="#friction">Friction</a><a href="#novel">Novel behavior</a><a href="#next">Next action</a><a href="#explorer">Journey explorer</a></nav><div class="side-foot" id="generated"></div></aside>
<main class="main"><header class="top"><div><div class="eyebrow">Unsupervised journey clustering</div><h1>__TITLE__</h1><p class="subtitle">User thực sự làm gì, gặp khó ở đâu và hành vi nào đang thay đổi.</p></div><div class="controls"><div class="control"><label>Platform</label><select id="platform"><option value="all">Android + iOS</option><option value="android">Android</option><option value="ios">iOS</option></select></div><div class="control"><label>Top clusters</label><select id="topN"><option>15</option><option>25</option><option>40</option><option>60</option></select></div></div></header>
<section id="overview" class="section"><div id="kpis" class="kpis"></div></section>
<section id="landscape" class="section"><div class="section-title"><div><h2>Cluster landscape</h2><p>Volume, tỷ lệ struggle và danh mục journey type.</p></div></div><div class="grid-2"><div class="panel"><h3>Clusters phổ biến nhất</h3><div class="hint">Thanh = số journey · màu đỏ = struggle rate</div><div id="clusterBars" class="bars"></div></div><div class="panel"><h3>Business family</h3><div class="hint">Cơ cấu traffic theo nhóm nghiệp vụ</div><div id="familyBars" class="bars"></div></div></div></section>
<section id="timing" class="section"><div class="section-title"><div><h2>User đang làm gì trong app?</h2><p>Diện tích = số lượng journey · màu = tỷ lệ journey mà user gặp khó khăn.</p></div></div><div class="panel"><div class="treemap-layout"><div><div class="treemap-frame" id="journeyTreemap"></div><div class="treemap-legend"><span>0%</span><span class="treemap-gradient"></span><span>100% struggle</span></div></div><div class="tree-side"><h3>Business family theo traffic</h3><div id="treeFamilyBars" class="bars"></div><div id="treeInsight" class="tree-insight"></div></div></div></div></section>
<section id="trend" class="section"><div class="section-title"><div><h2>Xu hướng production</h2><p>Tổng journey theo ngày và tỷ lệ novel behavior.</p></div></div><div class="grid-even"><div class="panel"><h3>Journey volume</h3><div id="volumeTrend"></div></div><div class="panel"><h3>Novel rate</h3><div id="novelTrend"></div></div></div></section>
<section id="friction" class="section"><div class="section-title"><div><h2>Khách hàng bị mắc kẹt ở đâu</h2><p>Tín hiệu hành vi và task nên ưu tiên cải thiện.</p></div></div><div class="grid-even"><div class="panel"><h3>Friction signals</h3><div id="flagBars" class="bars"></div></div><div class="panel"><h3>Journey type struggle cao</h3><div id="frictionBars" class="bars"></div></div></div></section>
<section id="novel" class="section"><div class="section-title"><div><h2>Novel behavior</h2><p>Journey nằm ngoài các type đã học.</p></div></div><div class="panel"><div id="novelSummary"></div></div></section>
<section id="next" class="section"><div class="section-title"><div><h2>User sẽ làm gì tiếp theo</h2><p>Tín hiệu để thiết kế shortcut, deep link và prompt.</p></div></div><div class="panel"><div id="nextBars" class="bars"></div></div></section>
<section id="catalog" class="section"><div class="section-title"><div><h2>Journey type catalogue</h2><p>Click header không cần thiết; dùng ô tìm kiếm để lọc nhanh.</p></div><input class="search" id="typeSearch" placeholder="Tìm type / family…"></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Journey type</th><th>Family</th><th>Journeys</th><th>Customers</th><th>Share</th><th>Struggle</th><th>Median steps</th><th>Median sec</th></tr></thead><tbody id="typeTable"></tbody></table></div></div></section>
<section id="explorer" class="section"><div class="section-title"><div><h2>Journey explorer</h2><p>Mẫu audit bounded; không dùng để tính thống kê.</p></div><div class="split"><select class="search" id="exampleFilter"><option value="all">Tất cả</option><option value="struggle">Có struggle</option><option value="clean">Không struggle</option></select><input class="search" id="exampleSearch" placeholder="Tìm journey / sequence…"></div></div><div class="panel" id="examples"></div></section>
<div class="footer">Generated from named inference journey summaries · no row-level production CSV is loaded by this page.</div></main></div>
<script id="dashboard-data" type="application/json">__DATA__</script>
<script>
const DATA=JSON.parse(document.getElementById('dashboard-data').textContent),T=DATA.tables;
const num=v=>Number(v||0), pct=v=>(num(v)*100).toFixed(num(v)<.1?1:0)+'%', int=v=>num(v).toLocaleString('en-US'), sec=v=>num(v)>=60?(num(v)/60).toFixed(1)+'m':num(v).toFixed(0)+'s';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let platform='all',topN=15;
const rows=(name)=>platform==='all'?T[name]:T[name].filter(r=>r.platform===platform);
const sumBy=(arr,key,val='journeys')=>Object.values(arr.reduce((a,r)=>{const k=r[key]||'__unknown__';(a[k]??={key:k,value:0,rateN:0,rateD:0});a[k].value+=num(r[val]);a[k].rateN+=num(r.struggle_rate)*num(r[val]);a[k].rateD+=num(r[val]);return a},{}));
function bars(id,data,{label='key',value='value',format=int,color='',rate=null,limit=15}={}){data=[...data].sort((a,b)=>num(b[value])-num(a[value])).slice(0,limit);const max=Math.max(1,...data.map(d=>num(d[value])));document.getElementById(id).innerHTML=data.length?data.map(d=>`<div class="bar-row"><div class="bar-label" title="${esc(d[label])}">${esc(d[label])}</div><div class="bar-track"><div class="bar-fill ${color}" style="width:${100*num(d[value])/max}%"></div></div><div class="bar-value">${format(d[value])}${rate?` · ${pct(d[rate])}`:''}</div></div>`).join(''):'<div class="empty">Không có dữ liệu</div>'}
function kpis(){let k=platform==='all'?T.kpi.find(r=>r.scope==='all'):T.kpi.find(r=>r.scope===platform);const cards=[['Journeys',int(k.journeys),'task được nhận diện'],['Sessions',int(k.sessions),(num(k.journeys)/Math.max(1,num(k.sessions))).toFixed(2)+' journey/session'],['Customers',int(k.customers),'distinct customer'],['Known journey',pct(k.known_rate),int(k.clusters)+' clusters'],['Có struggle',pct(k.struggle_rate),'tín hiệu hành vi'],['Median duration',sec(k.median_span_seconds),num(k.median_steps).toFixed(0)+' bước']];document.getElementById('kpis').innerHTML=cards.map(x=>`<div class="card kpi"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="note">${x[2]}</div></div>`).join('')}
function landscape(){let clusters=rows('cluster_summary').map(r=>({...r,label:`#${r.cluster} · ${r.journey_type}`,value:num(r.journeys)}));bars('clusterBars',clusters,{label:'label',rate:'struggle_rate',limit:topN});let fam=sumBy(rows('family_summary'),'business_family');bars('familyBars',fam,{limit:12})}
function treeRects(items,x,y,w,h){if(!items.length)return[];if(items.length===1)return[{...items[0],x,y,w,h}];items=[...items].sort((a,b)=>b.value-a.value);const total=items.reduce((s,d)=>s+d.value,0);let acc=0,cut=1,best=Infinity;for(let i=1;i<items.length;i++){acc+=items[i-1].value;const delta=Math.abs(total/2-acc);if(delta<best){best=delta;cut=i}}const a=items.slice(0,cut),b=items.slice(cut),av=a.reduce((s,d)=>s+d.value,0),ratio=av/total;if(w>=h)return[...treeRects(a,x,y,w*ratio,h),...treeRects(b,x+w*ratio,y,w*(1-ratio),h)];return[...treeRects(a,x,y,w,h*ratio),...treeRects(b,x,y+h*ratio,w,h*(1-ratio))]}
function mixColor(rate){const stops=[[76,120,168],[238,202,59],[228,87,86]],t=Math.max(0,Math.min(1,num(rate)));let a,b,u;if(t<.5){a=stops[0];b=stops[1];u=t*2}else{a=stops[1];b=stops[2];u=(t-.5)*2}return`rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*u)).join(',')})`}
function heatmap(){let raw=rows('journey_type_summary'),types={};for(const r of raw){const key=`${r.business_family}|${r.journey_type}`;(types[key]??={family:r.business_family,label:r.journey_type,value:0,rateN:0});let x=types[key],v=num(r.journeys);x.value+=v;x.rateN+=num(r.struggle_rate)*v}let families={};for(const x of Object.values(types)){x.rate=x.rateN/Math.max(1,x.value);(families[x.family]??={label:x.family,value:0,items:[]}).value+=x.value;families[x.family].items.push(x)}const familyList=Object.values(families),familyRects=treeRects(familyList,0,0,900,550);let svg='<svg class="treemap-svg" viewBox="0 0 900 550" role="img" aria-label="Treemap journey theo business family và journey type">';for(const f of familyRects){const pad=4,titleH=f.h>42?22:0;svg+=`<rect class="tree-family" x="${f.x+1}" y="${f.y+1}" width="${Math.max(0,f.w-2)}" height="${Math.max(0,f.h-2)}"/>`;if(titleH)svg+=`<text class="tree-family-label" x="${f.x+7}" y="${f.y+16}">${esc(f.label)}</text>`;const cells=treeRects(f.items,f.x+4,f.y+titleH+2,Math.max(0,f.w-8),Math.max(0,f.h-titleH-6));for(const c of cells){const title=`${c.family} · ${c.label} · ${int(c.value)} journey · ${pct(c.rate)} struggle`;svg+=`<g><title>${esc(title)}</title><rect class="tree-cell" x="${c.x}" y="${c.y}" width="${Math.max(0,c.w)}" height="${Math.max(0,c.h)}" fill="${mixColor(c.rate)}"/>`;if(c.w>68&&c.h>24){let label=c.label.length>Math.floor(c.w/7)?c.label.slice(0,Math.max(5,Math.floor(c.w/7)-1))+'…':c.label;svg+=`<text class="tree-label ${c.rate<.12?'light':''}" x="${c.x+5}" y="${c.y+15}">${esc(label)}</text>`}svg+='</g>'}}svg+='</svg>';document.getElementById('journeyTreemap').innerHTML=svg;let famBars=familyList.map(f=>({key:f.label,value:f.value}));bars('treeFamilyBars',famBars,{limit:14});const lead=[...familyList].sort((a,b)=>b.value-a.value)[0],total=familyList.reduce((s,f)=>s+f.value,0),familySource=rows('family_summary').filter(r=>r.business_family===lead.label),customers=familySource.reduce((s,r)=>s+num(r.customers),0);document.getElementById('treeInsight').innerHTML=`<strong>${esc(lead.label)}</strong> dẫn đầu traffic production với <strong>${pct(lead.value/Math.max(1,total))}</strong> tổng số journey, chạm tới khoảng <strong>${int(customers)}</strong> customer. Đây là trọng tâm sử dụng thực tế của app.`}
function svgLine(id,points,{rate=false,color=''}={}){const host=document.getElementById(id),W=700,H=285,p={l:48,r:15,t:15,b:35};if(!points.length){host.innerHTML='<div class="empty">Không có dữ liệu</div>';return}const vals=points.map(x=>x.v),max=Math.max(...vals,rate?.01:1),min=rate?0:Math.min(0,...vals),sx=i=>p.l+i*(W-p.l-p.r)/Math.max(1,points.length-1),sy=v=>H-p.b-(v-min)*(H-p.t-p.b)/(max-min||1);let line=points.map((x,i)=>`${i?'L':'M'}${sx(i).toFixed(1)},${sy(x.v).toFixed(1)}`).join(' '),area=`M${sx(0)},${H-p.b} `+line+` L${sx(points.length-1)},${H-p.b} Z`;let ticks='';for(let i=0;i<=4;i++){let y=p.t+i*(H-p.t-p.b)/4,v=max-i*(max-min)/4;ticks+=`<line class="axis" x1="${p.l}" x2="${W-p.r}" y1="${y}" y2="${y}"/><text class="tick" x="${p.l-7}" y="${y+3}" text-anchor="end">${rate?pct(v):int(v)}</text>`}for(let i=0;i<points.length;i+=Math.max(1,Math.ceil(points.length/6))){ticks+=`<text class="tick" x="${sx(i)}" y="${H-12}" text-anchor="middle">${points[i].x.slice(5)}</text>`}host.innerHTML=`<svg viewBox="0 0 ${W} ${H}" class="svg-chart">${ticks}<path class="area" d="${area}"/><path class="line ${color}" d="${line}"/></svg>`}
function trends(){let d=sumBy(rows('daily_trend'),'date');svgLine('volumeTrend',d.sort((a,b)=>a.key.localeCompare(b.key)).map(x=>({x:x.key,v:x.value})));let n=rows('novel_daily'),by={};for(const r of n){let x=by[r.date]??={x:r.date,n:0,d:0};x.n+=num(r.novel_journeys);x.d+=num(r.journeys)}svgLine('novelTrend',Object.values(by).sort((a,b)=>a.x.localeCompare(b.x)).map(x=>({x:x.x,v:x.n/Math.max(1,x.d)})),{rate:true,color:'red'})}
function friction(){let flags=sumBy(rows('friction_summary'),'flag');bars('flagBars',flags,{color:'red',limit:12});let f=sumBy(rows('friction_by_type'),'journey_type');f.forEach(x=>x.rate=x.rateN/Math.max(1,x.rateD));bars('frictionBars',f.sort((a,b)=>b.rate-a.rate).slice(0,12),{value:'rate',format:pct,color:'red',limit:12})}
function novel(){let d=rows('novel_daily'),journeys=d.reduce((s,r)=>s+num(r.journeys),0),novel=d.reduce((s,r)=>s+num(r.novel_journeys),0),customers=Math.max(0,...d.map(r=>num(r.novel_customers)));document.getElementById('novelSummary').innerHTML=`<div class="kpis" style="margin:0"><div class="kpi"><div class="label">Novel journeys</div><div class="value">${int(novel)}</div><div class="note">${pct(novel/Math.max(1,journeys))} tổng journey</div></div><div class="kpi"><div class="label">Peak daily rate</div><div class="value">${pct(Math.max(0,...d.map(r=>num(r.novel_rate))))}</div><div class="note">drift monitor</div></div><div class="kpi"><div class="label">Max customers/day</div><div class="value">${int(customers)}</div><div class="note">customer liên quan</div></div></div>`}
function next(){let d=sumBy(rows('next_action_summary'),'next_action');bars('nextBars',d,{limit:20})}
function catalogue(){const q=document.getElementById('typeSearch').value.toLowerCase().trim();let data=rows('journey_type_summary');if(platform==='all'){let g={};for(const r of data){const k=r.journey_type;(g[k]??={journey_type:k,business_family:r.business_family,journeys:0,customers:0,platform_share:0,struggleN:0,struggleD:0,median_steps:0,median_span_seconds:0,n:0});let x=g[k],w=num(r.journeys);x.journeys+=w;x.customers+=num(r.customers);x.struggleN+=num(r.struggle_rate)*w;x.struggleD+=w;x.median_steps+=num(r.median_steps);x.median_span_seconds+=num(r.median_span_seconds);x.n++}data=Object.values(g).map(x=>({...x,struggle_rate:x.struggleN/Math.max(1,x.struggleD),median_steps:x.median_steps/x.n,median_span_seconds:x.median_span_seconds/x.n,platform_share:x.journeys/T.kpi.find(r=>r.scope==='all').journeys}))}data=data.filter(r=>(r.journey_type+' '+r.business_family).toLowerCase().includes(q)).sort((a,b)=>num(b.journeys)-num(a.journeys));document.getElementById('typeTable').innerHTML=data.map(r=>`<tr><td><strong>${esc(r.journey_type)}</strong></td><td>${esc(r.business_family)}</td><td>${int(r.journeys)}</td><td>${int(r.customers)}</td><td>${pct(r.platform_share)}</td><td><span class="pill ${num(r.struggle_rate)>.3?'bad':''}">${pct(r.struggle_rate)}</span></td><td>${num(r.median_steps).toFixed(0)}</td><td>${sec(r.median_span_seconds)}</td></tr>`).join('')}
function examples(){const q=document.getElementById('exampleSearch').value.toLowerCase().trim(),mode=document.getElementById('exampleFilter').value;let data=rows('journey_examples').filter(r=>(mode==='all'||(mode==='struggle')===(r.has_struggle==='true'))&&(r.journey_type+' '+r.sequence+' '+r.journey_id).toLowerCase().includes(q)).slice(0,80);document.getElementById('examples').innerHTML=data.length?data.map(r=>`<div class="journey"><div class="journey-head"><div><div class="journey-title">${esc(r.journey_type)}</div><div class="meta">${esc(r.platform)} · cluster ${esc(r.cluster)} · ${esc(r.start_ts)} · ${num(r.n_events_final).toFixed(0)} bước · ${sec(r.span_seconds)}</div></div><span class="pill ${r.has_struggle==='true'?'bad':''}">${r.has_struggle==='true'?'struggle':'clean'}</span></div><details><summary>Xem sequence và audit trail</summary><div class="meta">${esc(r.journey_id)}<br>Entry: ${esc(r.entry_token)}<br>Exit: ${esc(r.exit_token)}<br>Next: ${esc(r.next_action||'—')}</div><pre>${esc(r.sequence).replace(/ -&gt; /g,'\n→ ')}</pre></details></div>`).join(''):'<div class="empty">Không có journey phù hợp</div>'}
function render(){kpis();landscape();heatmap();trends();friction();novel();next();catalogue();examples()}
document.getElementById('platform').onchange=e=>{platform=e.target.value;render()};document.getElementById('topN').onchange=e=>{topN=num(e.target.value);landscape()};document.getElementById('typeSearch').oninput=catalogue;document.getElementById('exampleSearch').oninput=examples;document.getElementById('exampleFilter').onchange=examples;
document.getElementById('generated').textContent='Generated '+(DATA.manifest.generated_at||'').slice(0,10);render();
</script></body></html>'''


if __name__ == "__main__":
    build(parse_args())
